Summary:
[{
    "SDK_name": "Vungle SDK", 
    "API_name": "updateUserCoppaStatus", 
    "conditions": [
        "Vungle SDK must be initialized before this API is called.", 
        "The application needs to define if the user is under 13 years of age.",
        "Before the initialization of the Vungle SDK."
    ], 
    "effects": [
        "Sets the users’ COPPA status in the SDK.", 
        "This helps the app to comply with the Children’s Online Privacy Protection Act (COPPA) by suggesting the user's age to Vungle."
    ], 
    "parameter_configuations": [ 
      {
	      "parameter_values":["true"], 
	      "conditions":["To be used when it is known or determined that the user of the app is under the age of 13."], 
	      "effects":["Treats the user as under the age of 13 and in compliance with COPPA regulations"] 
      },{
          "parameter_values":["false"], 
	      "conditions":["To be used when it's known or determined that the user of the app is over the age of 13."], 
	      "effects":["Treats the user as over the age of 13 and not falling under COPPA regulations"] 
      }
    ]
  }]
